<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useCoffee} from '../stores/coffee';import {money} from '../../../../packages/shared/src/domain';import type {Product} from '../../../../packages/shared/src/types';import Modal from '../../../../packages/ui/src/Modal.vue';import Icon from '../components/Icon.vue';import ProductPhoto from '../components/ProductPhoto.vue';
const s=useCoffee();const route=useRoute();const query=ref('');const category=ref('all');const showArchived=ref(false);const editing=ref(false);const error=ref('');const form=ref<Product>();const archiveTarget=ref<Product>();
const images=computed(()=>Boolean(route.meta.images));const products=computed(()=>s.state.products.filter(p=>(showArchived.value||p.active)&&(category.value==='all'||p.category===category.value)&&p.name.toLowerCase().includes(query.value.toLowerCase())));
function edit(product?:Product){error.value='';form.value=product?JSON.parse(JSON.stringify(product)):{id:crypto.randomUUID(),name:'',description:'',price:35000,category:s.state.categories[0]?.id??'',active:true,available:true,photo:0,variants:[{id:'m',name:'M',delta:0},{id:'l',name:'L',delta:10000}],options:[]};editing.value=true}
function save(){if(!form.value)return;const result=s.upsert('products',form.value);if(result)editing.value=false}
function variant(){form.value?.variants.push({id:crypto.randomUUID(),name:'',delta:0})}
function option(){form.value?.options.push({id:crypto.randomUUID(),name:'',price:0})}
async function photo(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!form.value)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500000){error.value='Chọn ảnh PNG/JPEG/WebP dưới 500 KB.';return}const reader=new FileReader();reader.onload=()=>{if(form.value)form.value.image=String(reader.result)};reader.readAsDataURL(file)}
function archive(){if(archiveTarget.value&&s.archive('products',archiveTarget.value.id))archiveTarget.value=undefined}
</script><template><div class="page"><div class="page-heading"><div><h2>{{images?'Thư viện hình ảnh':'Quản lý thực đơn'}}</h2><p>{{images?'Hình ảnh rõ nét giúp khách chọn món dễ hơn.':'Sản phẩm, giá, size và topping — quản lý cùng một nơi.'}}</p></div><button class="btn primary" v-if="s.canManage" @click="edit()"><Icon name="plus"/>Thêm sản phẩm</button></div><div class="filters"><label class="search-field"><Icon name="search"/><input v-model="query" placeholder="Tìm sản phẩm..." aria-label="Tìm sản phẩm"></label><select v-model="category" aria-label="Lọc danh mục"><option value="all">Tất cả danh mục</option><option v-for="c in s.state.categories" :value="c.id" :key="c.id">{{c.name}}</option></select><label class="check-row compact"><input type="checkbox" v-model="showArchived">Hiện món đã ngừng</label></div><div v-if="images" class="image-library"><article v-for="p in products" :key="p.id" class="panel"><ProductPhoto :photo="p.photo" :image="p.image" :name="p.name"/><div><h3>{{p.name}}</h3><small>{{p.image?'Ảnh đã tải lên':'Ảnh minh họa đồ uống'}}</small><button class="btn outline small" @click="edit(p)" :disabled="!s.canManage"><Icon name="image" :size="16"/>Thay ảnh</button></div></article></div><div v-else class="panel table-scroll"><table class="data-table"><thead><tr><th>Sản phẩm</th><th>Danh mục</th><th>Giá bán</th><th>Tùy chọn</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><div class="product-cell"><ProductPhoto :photo="p.photo" :image="p.image" :name="p.name"/><div><strong>{{p.name}}</strong><small>{{p.description}}</small></div></div></td><td>{{s.state.categories.find(c=>c.id===p.category)?.name}}</td><td class="numeric strong">{{money(p.price)}}</td><td>{{p.variants.length}} size<small>{{p.options.length}} topping</small></td><td><button class="status" :class="!p.active?'cancelled':p.available?'served':'pending'" :disabled="!s.canManage||!p.active" @click="s.upsert('products',{...p,available:!p.available})">{{!p.active?'Ngừng bán':p.available?'Đang bán':'Hết hàng'}}</button></td><td><div class="row-actions"><button class="icon-button" :aria-label="'Sửa '+p.name" :disabled="!s.canManage" @click="edit(p)"><Icon name="edit" :size="18"/></button><button class="icon-button" :aria-label="'Ngừng '+p.name" :disabled="!s.canManage||!p.active" @click="archiveTarget=p"><Icon name="trash" :size="18"/></button></div></td></tr></tbody></table><div v-if="!products.length" class="empty"><Icon name="coffee" :size="36"/><h3>Chưa có sản phẩm phù hợp</h3><p>Đổi bộ lọc hoặc thêm món mới.</p></div></div></div>
<Modal v-if="editing&&form" :title="s.state.products.some(p=>p.id===form!.id)?'Sửa sản phẩm':'Thêm sản phẩm'" wide @close="editing=false"><form @submit.prevent="save"><div class="product-form-grid"><section><label class="field"><span>Tên sản phẩm</span><input required maxlength="100" v-model="form.name" aria-label="Tên sản phẩm"></label><div class="form-row"><label class="field"><span>Giá bán (đ)</span><input type="number" min="0" step="1000" required v-model.number="form.price" aria-label="Giá bán"></label><label class="field"><span>Danh mục</span><select v-model="form.category"><option v-for="c in s.state.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><label class="field"><span>Mô tả món</span><textarea v-model="form.description" maxlength="300"></textarea></label><div class="check-pair"><label class="check-row"><input type="checkbox" v-model="form.available">Còn hàng</label><label class="check-row"><input type="checkbox" v-model="form.active">Đang bán</label></div><h3>Size <button type="button" class="text-link" @click="variant">+ Thêm size</button></h3><div v-for="(v,i) in form.variants" :key="v.id" class="option-edit-row"><input required v-model="v.name" placeholder="Tên size" :aria-label="'Tên size '+(i+1)"><input required min="0" type="number" v-model.number="v.delta" :aria-label="'Phụ thu size '+(i+1)"><button type="button" class="icon-button" :disabled="form.variants.length===1" :aria-label="'Xóa size '+v.name" @click="form!.variants.splice(i,1)"><Icon name="close" :size="16"/></button></div><h3>Topping <button type="button" class="text-link" @click="option">+ Thêm topping</button></h3><div v-for="(o,i) in form.options" :key="o.id" class="option-edit-row"><input required v-model="o.name" placeholder="Tên topping" :aria-label="'Tên topping '+(i+1)"><input required type="number" min="0" v-model.number="o.price" :aria-label="'Giá topping '+(i+1)"><button type="button" class="icon-button" :aria-label="'Xóa topping '+o.name" @click="form!.options.splice(i,1)"><Icon name="close" :size="16"/></button></div></section><section><ProductPhoto class="editor-photo" :photo="form.photo" :image="form.image" :name="form.name"/><label class="file-picker"><Icon name="image"/>Tải ảnh lên<input type="file" accept="image/png,image/jpeg,image/webp" @change="photo" aria-label="Tải ảnh sản phẩm"></label><p class="muted small-copy">PNG, JPEG hoặc WebP, tối đa 500 KB. Ảnh lưu trên trình duyệt.</p><button v-if="form.image" type="button" class="text-link" @click="form.image=''">Gỡ ảnh đã tải</button><label v-if="!form.image" class="field"><span>Ảnh minh họa</span><select v-model.number="form.photo"><option v-for="(name,i) in ['Cà phê sữa','Americano','Latte','Trà đào','Matcha','Bạc xỉu']" :key="i" :value="i">{{name}}</option></select></label><p v-if="error" class="inline-error" role="alert">{{error}}</p></section></div><div class="modal-footer"><button type="button" class="btn outline" @click="editing=false">Hủy</button><button class="btn primary" :disabled="!s.canManage">Lưu sản phẩm</button></div></form></Modal>
<Modal v-if="archiveTarget" title="Ngừng bán sản phẩm" @close="archiveTarget=undefined"><p>Ngừng bán <strong>{{archiveTarget.name}}</strong>? Món vẫn được giữ trong lịch sử bill đã xuất.</p><div class="modal-footer"><button class="btn outline" @click="archiveTarget=undefined">Giữ lại</button><button class="btn danger" @click="archive">Ngừng bán</button></div></Modal></template>
